style.css:
@-moz-document domain("pinterest.com") {
html {
    box-sizing: border-box;
  }
  *, *::before, *::after {
    box-sizing: inherit;
    margin: 0;
    padding: 0;
  }
  body {
    background-color: #f0f9f4 !important;
    background-image: url('https://www.transparenttextures.com/patterns/floral-white.png') !important;
    background-repeat: repeat !important;
    color: #2e4d36 !important;
    font-family: 'Segoe UI', system-ui, sans-serif !important;
  }
  img[alt="Pinterest"][src*="logo"] {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    overflow: hidden !important;
    white-space: nowrap !important;
    border: 0 !important;
    opacity: 0 !important;
    background-image: url("https://images.unsplash.com/photo-1581349485022-4b2f8f6e70e3?auto=format&fit=crop&w=100&q=80") !important;
    background-repeat: no-repeat !important;
    background-size: contain !important;
  }
  div[data-test-id="pinGrid"] {
    display: flex !important;
    flex-wrap: wrap !important;
    padding: 2rem !important;
    margin: 0 -0.75rem !important;
  }
  div[data-test-id="pinGrid"] > div {
    flex: 1 1 calc(33.333% - 1.5rem) !important;
    padding: 0 0.75rem !important;
  }
  @media (max-width: 900px) {
    div[data-test-id="pinGrid"] > div {
      flex-basis: calc(50% - 1.5rem) !important;
    }
  }
  @media (max-width: 600px) {
    div[data-test-id="pinGrid"] > div {
      flex-basis: 100% !important;
    }
  }
  div[data-test-id="pin"] {
    background-color: #ffffff !important;
    border-radius: 20px !important;
    box-shadow: 0 6px 14px rgba(60, 100, 75, 0.15) !important;
    overflow: hidden !important;
    border: 1px solid #d6eadd !important;
    transition: box-shadow 0.3s ease, transform 0.3s ease !important;
    padding: 0.5rem !important;
  }
  div[data-test-id="pin"] img {
    display: block !important;
    width: 100% !important;
    height: 180px !important;
    object-fit: cover !important;
    border-radius: 15px !important;
    transition: transform 0.4s ease !important;
  }
  div[data-test-id="pin"]:hover {
    box-shadow: 0 10px 24px rgba(60, 100, 75, 0.25) !important;
    transform: translateY(-6px) !important;
  }
  div[data-test-id="pin"]:hover img {
    transform: scale(1.04) !important;
  }
}
